import React, { useMemo, useState } from "react";
import { Download, FileSpreadsheet, FileText, HelpCircle, Mail, X, CheckCircle2, Paperclip, ChevronDown, Plus, Users, Clock3, CalendarDays, Pencil, Trash2, Save, AlertTriangle, Layers } from "lucide-react";
import { jsPDF } from "jspdf";
import * as XLSX from "xlsx";
import Sidebar from "./Sidebar";
import PayslipTypes from "./PayslipTypes";
import "./Payslip.css";

const monthOptions = Array.from({ length: 12 }, (_, i) => {
  const date = new Date(); date.setDate(1); date.setMonth(date.getMonth() - i);
  return { value: `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}`, label: date.toLocaleDateString("en-IN", { month: "long", year: "numeric" }) };
});
const currentMonth = monthOptions[0].value;
const PAYSLIP_TYPES = ["Fixed Pay", "Hourly Pay", "Daily Wage", "Weekly Pay", "Monthly Pay", "Commission-Based Pay", "Piece-Rate Pay", "Contract-Based Pay"];
const money = (value) => `₹${Math.round(value).toLocaleString("en-IN")}`;
const componentsFor = (employee, period = employee.payPeriod) => employee.payslipComponentsByPeriod?.[period] || employee.payslipComponents;
const earningsOf = (employee, period = employee.payPeriod) => componentsFor(employee, period)?.earnings || [{ id: "basic", label: "Basic Salary", value: employee.basic, source: "basic" }, { id: "hra", label: "House Rent Allowance (HRA)", value: employee.hra, source: "hra" }, { id: "special", label: "Special Allowance", value: employee.special, source: "special" }, { id: "overtime", label: "Overtime Pay", value: employee.overtimePay || 0, source: "overtimePay" }, { id: "other-allowances", label: "Other Allowances", value: 0 }];
const deductionsOf = (employee, period = employee.payPeriod) => componentsFor(employee, period)?.deductions || [{ id: "pf", label: "Provident Fund (PF)", value: employee.pf, source: "pf" }, { id: "tax", label: "Professional Tax", value: employee.tax, source: "tax" }, { id: "income-tax", label: "Income Tax / TDS", value: 0 }, { id: "unpaid-leave", label: "Unpaid Leave Deduction", value: 0 }, { id: "other-deductions", label: "Other Deductions", value: employee.otherDeductions, source: "otherDeductions" }];
const calculateTypePay = (employee, type, period = employee.payPeriod) => {
  const components = componentsFor(employee, period);
  const items = earningsOf(employee, period);
  const extras = items.filter((item) => !["basic", "hra", "special", "overtime"].includes(item.id)).reduce((sum, item) => sum + Number(item.value || 0), 0);
  const allowances = items.filter((item) => !["basic", "overtime"].includes(item.id)).reduce((sum, item) => sum + Number(item.value || 0), 0);
  const monthlySalary = items.filter((item) => ["basic", "hra", "special"].includes(item.id)).reduce((sum, item) => sum + Number(item.value || 0), 0) || employee.basic + employee.hra + employee.special;
  const deductions = components?.deductions ? deductionsOf(employee, period).reduce((sum, item) => sum + Number(item.value || 0), 0) : employee.pf + employee.tax + employee.otherDeductions;
  const input = { monthlySalary, hourlyRate: 250, regularHours: employee.hours || 160, overtimeHours: employee.overtimePay ? 4 : 0, overtimeRate: employee.overtimePay ? employee.overtimePay / 4 : 375, dailyRate: 1600, payableDays: employee.days || 20, weeklyRate: 12000, payableWeeks: 4, monthlyRate: monthlySalary, salesBase: 200000, commissionRate: 0.05, fixedComponent: 5000, eligibleUnits: 400, unitRate: 80, contractAmount: 60000, contractPayable: 30000, ...(employee.calculationInputsByPeriod?.[period] || {}) };
  let earnings;
  if (type === "Fixed Pay") earnings = input.monthlySalary / 22 * input.payableDays + input.overtimeHours * input.overtimeRate + extras;
  else if (type === "Hourly Pay") earnings = input.regularHours * input.hourlyRate + input.overtimeHours * input.overtimeRate + allowances;
  else if (type === "Daily Wage") earnings = input.payableDays * input.dailyRate + input.overtimeHours * input.overtimeRate + allowances;
  else if (type === "Weekly Pay") earnings = input.payableWeeks * input.weeklyRate + allowances;
  else if (type === "Monthly Pay") earnings = input.monthlyRate + extras;
  else if (type === "Commission-Based Pay") earnings = input.fixedComponent + input.salesBase * input.commissionRate + allowances;
  else if (type === "Piece-Rate Pay") earnings = input.eligibleUnits * input.unitRate + allowances;
  else if (type === "Contract-Based Pay") earnings = input.contractPayable + allowances;
  else earnings = components?.earnings ? items.reduce((sum, item) => sum + Number(item.value || 0), 0) : employee.basic + employee.hra + employee.special + (employee.overtimePay || 0);
  return { earnings, deductions, net: earnings - deductions };
};
const pay = (employee, period = employee.payPeriod, type = employee.payslipType || null) => calculateTypePay(employee, type, period);
const makeEmployee = ([name, id, department, email, basic, hra, special, pf, tax, otherDeductions, approval, status, emailStatus, overtimePay = 0]) => ({ name, id, department, email, designation: "People Team", basic, hra, special, pf, tax, otherDeductions, approval, status, emailStatus, overtimePay, days: 22, hours: 176, leaves: 1, joining: "2022-04-15", payPeriod: currentMonth });
const INITIAL_EMPLOYEES = [
  ["Janani S", "EMP001", "Engineering", "janani@lernevo.com", 32000, 12000, 4500, 2400, 200, 300, "Approved", "Generated", "Sent", 1800],
  ["Arun Kumar", "EMP002", "Design", "arun@lernevo.com", 28000, 10000, 3500, 2100, 200, 150, "Approved", "Generated", "Not Sent"],
  ["Meena P", "EMP003", "Product", "meena@lernevo.com", 41000, 16000, 6000, 3000, 200, 500, "Pending approval", "Pending", "Not Sent"],
  ["Karthik R", "EMP004", "Marketing", "karthik@lernevo.com", 30000, 12000, 4200, 2200, 200, 200, "Approved", "Generated", "Not Sent", 900],
  ["Priya S", "EMP005", "HR", "priya@lernevo.com", 26000, 10000, 3200, 1900, 200, 100, "Approved", "Pending", "Not Sent"],
  ["Vijay T", "EMP006", "Sales", "vijay@lernevo.com", 29000, 11000, 5500, 2200, 200, 800, "Approved", "Generated", "Not Sent", 2400],
  ["Nisha R", "EMP007", "Engineering", "nisha@lernevo.com", 27000, 10500, 3200, 2000, 200, 100, "Approved", "Pending", "Not Sent"],
  ["Rahul M", "EMP008", "Design", "rahul@lernevo.com", 31000, 12000, 3800, 2300, 200, 250, "Approved", "Generated", "Not Sent"],
  ["Divya K", "EMP009", "Product", "divya@lernevo.com", 35000, 14000, 4800, 2600, 200, 300, "Missing timesheet", "Pending", "Not Sent"],
  ["Sanjay V", "EMP010", "Sales", "sanjay@lernevo.com", 33000, 12500, 4700, 2450, 200, 350, "Approved", "Generated", "Not Sent"],
  ["Anita D", "EMP011", "HR", "anita@lernevo.com", 25000, 9500, 3000, 1800, 200, 100, "Missing payroll data", "Pending", "Not Sent"],
  ["Rohit B", "EMP012", "Marketing", "rohit@lernevo.com", 29000, 11000, 3900, 2100, 200, 250, "Approved", "Generated", "Failed"],
].map(makeEmployee);
// Frontend-only prototype mapping. Replace with the employee.team relationship
// when the Payslips data source exposes team assignments. Payroll records remain untouched.
const DEMO_TEAM_ASSIGNMENTS = [
  { id: "A", label: "Team A", employeeIds: ["EMP003", "EMP005", "EMP007", "EMP009"] },
  { id: "B", label: "Team B", employeeIds: ["EMP001", "EMP002"] },
  { id: "C", label: "Team C", employeeIds: ["EMP004", "EMP006"] },
  { id: "D", label: "Team D", employeeIds: ["EMP008", "EMP010"] },
  { id: "E", label: "Team E", employeeIds: ["EMP011", "EMP012"] },
];
const TEMPLATES = {
  "Payslip — Default Template": { subject: "Your Payslip for {{pay_period}} — {{company_name}}", message: "Hi {{employee_name}},\n\nPlease find attached your payslip for {{pay_period}}.\n\nYour net pay for this period is {{net_pay}}.\n\nIf you have any questions regarding your salary statement, please contact the HR team.\n\nRegards,\n{{company_name}} HR Team" },
  "Monthly Salary Statement": { subject: "Monthly salary statement | {{pay_period}}", message: "Dear {{employee_name}},\n\nYour salary statement for {{pay_period}} is ready. Net pay: {{net_pay}}.\n\nPlease see your individual payslip attached. For assistance, contact the HR team.\n\nRegards,\n{{company_name}} HR Team" },
  "Custom Email Template": { subject: "Payslip enclosed for {{pay_period}}", message: "Hello {{employee_name}},\n\nAttached is your payslip for {{pay_period}}. Your net pay is {{net_pay}}.\n\nThank you,\n{{company_name}} HR Team" },
};

export default function Payslip() {
  const [employees, setEmployees] = useState(INITIAL_EMPLOYEES);
  const [teams, setTeams] = useState(() => DEMO_TEAM_ASSIGNMENTS.map((team) => ({ ...team, departments: [...new Set(INITIAL_EMPLOYEES.filter((employee) => team.employeeIds.includes(employee.id)).map((employee) => employee.department))], description: "" })));
  const [month, setMonth] = useState(currentMonth);
  const [showPayslipTypes, setShowPayslipTypes] = useState(false);
  const [dialog, setDialog] = useState(null);
  const [notice, setNotice] = useState("");
  const [savedRemarks, setSavedRemarks] = useState({});
  const isAdmin = (() => { try { const user = JSON.parse(localStorage.getItem("lernevo_user") || localStorage.getItem("user") || "{}"); return ["SUPER_ADMIN", "ADMIN"].includes(String(user.role || user.user_role || localStorage.getItem("role") || "SUPER_ADMIN").toUpperCase()); } catch { return String(localStorage.getItem("role") || "SUPER_ADMIN").toUpperCase() === "SUPER_ADMIN"; } })();
  const [busy, setBusy] = useState(false);
  const [template, setTemplate] = useState(Object.keys(TEMPLATES)[0]);
  const [attachPdf, setAttachPdf] = useState(true);
  const [emailPreviewId, setEmailPreviewId] = useState(null);
  const [exportFields, setExportFields] = useState({ details: true, breakdown: true, net: true });
  const [expandedTeam, setExpandedTeam] = useState(null);
  const [teamDepartmentFilter, setTeamDepartmentFilter] = useState("All departments");
  const [teamEmployeeFilter, setTeamEmployeeFilter] = useState("All Employees");
  const [teamPayslipTypes, setTeamPayslipTypes] = useState({ A: "Fixed Pay", B: "Monthly Pay", C: "Hourly Pay", D: "Daily Wage", E: "Weekly Pay" });
  const [employeePayslipTypes, setEmployeePayslipTypes] = useState({ EMP005: "Hourly Pay", EMP006: "Commission-Based Pay", EMP008: "Piece-Rate Pay", EMP012: "Contract-Based Pay" });
  const effectiveType = (employee, teamId) => ({ type: employeePayslipTypes[employee.id] || teamPayslipTypes[teamId] || null, source: employeePayslipTypes[employee.id] ? "Individual override" : teamPayslipTypes[teamId] ? "Inherited from team" : "Not Assigned" });

  const generated = employees.filter((e) => e.status === "Generated" && e.payPeriod === month && effectiveType(e, teams.find((team) => team.employeeIds.includes(e.id))?.id).type);
  const rows = useMemo(() => employees.filter((employee) => employee.status === "Pending" || (employee.status === "Generated" && employee.payPeriod === month)), [employees, month]);
  const selectedPreviewRecord = employees.find((e) => e.id === dialog?.employeeId) || employees[0];
  const selectedPreviewPeriod = dialog?.period || month;
  const selectedEmployeeTeam = teams.find((team) => team.employeeIds.includes(selectedPreviewRecord?.id));
  const selectedPreviewType = selectedPreviewRecord ? effectiveType(selectedPreviewRecord, selectedEmployeeTeam?.id) : { type: null, source: "Not Assigned" };
  const selectedPreview = selectedPreviewRecord ? { ...selectedPreviewRecord, payslipType: selectedPreviewType.type, payslipTypeSource: selectedPreviewType.source, ...(selectedPreviewRecord.calculationInputsByPeriod?.[selectedPreviewPeriod] || {}), payslipComponents: selectedPreviewRecord.payslipComponentsByPeriod?.[selectedPreviewPeriod] || selectedPreviewRecord.payslipComponents } : null;
  const selectedTeamName = teams.find((team) => team.employeeIds.includes(selectedPreview?.id))?.label || "Not assigned";
  const previewMonth = monthOptions.find((m) => m.value === (dialog?.period || month))?.label || dialog?.period || month;
  const teamGroups = useMemo(() => teams.map((team) => {
    const members = employees.filter((employee) => team.employeeIds.includes(employee.id));
    const periodMembers = members.filter((employee) => employee.payPeriod === month || employee.status === "Pending");
    const departmentCounts = [...new Set(members.map((employee) => employee.department))].map((name) => ({ name, count: members.filter((employee) => employee.department === name).length }));
    const badgeNames = [...new Set(team.departments || departmentCounts.map((item) => item.name))];
    return { ...team, members, departmentCounts: badgeNames.map((name) => ({ name, count: members.filter((employee) => employee.department === name).length })), generated: periodMembers.filter((employee) => employee.status === "Generated").length, pending: periodMembers.filter((employee) => employee.status === "Pending").length, net: periodMembers.reduce((sum, employee) => sum + pay(employee, month, effectiveType(employee, team.id).type).net, 0) };
  }), [employees, month, teams, teamPayslipTypes, employeePayslipTypes]);

  const updateNotice = (message) => { setNotice(message); window.setTimeout(() => setNotice(""), 4500); };
  const closeDialog = () => { if (!busy) setDialog(null); };
  const downloadPdf = (employee) => {
    const periodKey = dialog?.period || employee.payPeriod; const p = pay(employee, periodKey, employee.payslipType); const period = monthOptions.find((m) => m.value === periodKey)?.label || periodKey;
    const doc = new jsPDF(); doc.setFillColor(37, 99, 235); doc.rect(0, 0, 210, 38, "F"); doc.setTextColor(255, 255, 255); doc.setFontSize(19); doc.text("LERNEVO", 18, 19); doc.setFontSize(10); doc.text(`PAYSLIP · ${period}`, 18, 29);
    doc.setTextColor(30, 41, 59); doc.setFontSize(12); doc.text("Employee information", 18, 53); doc.setFontSize(10); doc.text(`Name: ${employee.name}     Employee ID: ${employee.id}`, 18, 63); doc.text(`Email: ${employee.email}`, 18, 71); doc.text(`Department: ${employee.department}     Pay period: ${period}`, 18, 79);
    doc.text("Earnings", 18, 98); doc.text("Deductions", 112, 98);
    [...earningsOf(employee, periodKey).map(({ label, value }) => [label, value]), ["Total Earnings", p.earnings]].forEach(([label, value], i) => { doc.text(label, 18, 109 + i * 9); doc.text(money(value), 90, 109 + i * 9, { align: "right" }); });
    [...deductionsOf(employee, periodKey).map(({ label, value }) => [label, value]), ["Total Deductions", p.deductions]].forEach(([label, value], i) => { doc.text(label, 112, 109 + i * 9); doc.text(money(value), 192, 109 + i * 9, { align: "right" }); });
    doc.setFillColor(239, 246, 255); doc.roundedRect(18, 160, 174, 20, 3, 3, "F"); doc.setTextColor(37, 99, 235); doc.setFontSize(13); doc.text("Net Pay", 24, 173); doc.text(money(p.net), 186, 173, { align: "right" }); doc.setTextColor(100, 116, 139); doc.setFontSize(8); doc.text("Demo payslip for presentation purposes only", 18, 275);
    doc.save(`${employee.name.replace(/\s+/g, "_")}_Payslip_${periodKey.replace("-", "")}.pdf`);
  };

  const generate = () => {
    const targets = employees.filter((e) => dialog.ids.includes(e.id) && e.status === "Pending" && e.approval === "Approved" && effectiveType(e, teams.find((team) => team.employeeIds.includes(e.id))?.id).type);
    if (!targets.length) return updateNotice("No selected employees are eligible. Assign a payslip type and review approval and payroll data.");
    setBusy(true);
    window.setTimeout(() => {
      const payslipNumbers = Object.fromEntries(targets.map((e, i) => [e.id, `LRN-${dialog.period.replace("-", "")}-${String(Date.now()).slice(-4)}${i}`]));
      setEmployees((current) => current.map((e) => targets.some((target) => target.id === e.id) ? { ...e, status: "Generated", payPeriod: dialog.period, emailStatus: "Not Sent", payslipNumber: payslipNumbers[e.id] } : e));
      setBusy(false); setDialog({ type: "generate", phase: "success", ids: targets.map((e) => e.id), period: dialog.period });
    }, 800);
  };
  const startEmployeeGeneration = (employee) => {
    const team = teams.find((item) => item.employeeIds.includes(employee.id));
    if (!effectiveType(employee, team?.id).type) return updateNotice("Assign a payslip type before generating this employee’s payslip.");
    if (employee.status !== "Pending") return updateNotice("This employee does not have a pending payslip to generate.");
    if (employee.approval !== "Approved") return updateNotice(`Generation is blocked: ${employee.approval}.`);
    setDialog({ type: "generate", phase: "review", ids: [employee.id], employeeId: employee.id, period: month });
  };
  const saveTeam = (values) => {
    const label = values.label.trim();
    if (!label) return updateNotice("Enter a team name before saving.");
    if (teams.some((team) => team.id !== values.id && team.label.toLowerCase() === label.toLowerCase())) return updateNotice("A team with that name already exists.");
    if (values.id) {
      const team = teams.find((item) => item.id === values.id);
      const usedDepartments = employees.filter((employee) => team?.employeeIds.includes(employee.id)).map((employee) => employee.department);
      const removedInUse = usedDepartments.find((department) => !values.departments.includes(department));
      if (removedInUse) return updateNotice(`${removedInUse} still has assigned employees. Change those employee departments before removing it from the team.`);
      setTeams((current) => current.map((item) => item.id === values.id ? { ...item, label, departments: values.departments, description: values.description.trim() } : item));
      setTeamPayslipTypes((current) => ({ ...current, [values.id]: values.payslipType }));
    }
    else {
      const id = `T${Date.now()}`;
      setTeams((current) => [...current, { id, label, employeeIds: [], departments: values.departments, description: values.description.trim() }]);
      setTeamPayslipTypes((current) => ({ ...current, [id]: values.payslipType }));
    }
    setDialog(null); updateNotice(values.id ? `${label} was updated in this demo.` : `${label} was added in this demo.`);
  };
  const removeTeam = (teamId) => {
    const team = teams.find((item) => item.id === teamId);
    const count = team?.employeeIds.length || 0;
    if (count) return updateNotice(`${team.label} still has ${count} assigned employee${count === 1 ? "" : "s"}. Reassign or remove them first.`);
    setTeams((current) => current.filter((item) => item.id !== teamId)); setExpandedTeam(null); setDialog(null); updateNotice(`${team?.label || "Team"} was deleted from this demo.`);
  };
  const saveEmployeeAssignment = ({ employeeId, teamId, department, payPeriod, payslipType }) => {
    const team = teams.find((item) => item.id === teamId);
    if (!team) return updateNotice("Choose a team before saving.");
    setTeams((current) => current.map((item) => ({ ...item, employeeIds: item.id === teamId ? [...new Set([...item.employeeIds, employeeId])] : item.employeeIds.filter((id) => id !== employeeId), departments: item.id === teamId ? [...new Set([...(item.departments || []), department])] : item.departments })));
    setEmployees((current) => current.map((employee) => employee.id === employeeId ? { ...employee, department, payPeriod } : employee));
    if (payslipType !== undefined) {
      setEmployeePayslipTypes((current) => {
        const next = { ...current };
        if (payslipType) next[employeeId] = payslipType;
        else delete next[employeeId];
        return next;
      });
    }
    setExpandedTeam(teamId); setTeamDepartmentFilter("All departments"); setTeamEmployeeFilter("All Employees"); setDialog(null); updateNotice("Employee assignment was updated in this demo.");
  };
  const removeEmployeeAssignment = ({ employeeId, teamId }) => {
    const employee = employees.find((item) => item.id === employeeId);
    setTeams((current) => current.map((team) => team.id === teamId ? { ...team, employeeIds: team.employeeIds.filter((id) => id !== employeeId) } : team));
    setDialog(null); updateNotice(`${employee?.name || "Employee"} was removed from this team. Their employee record and payslip history remain.`);
  };
  const savePayrollComponents = (employeeId, period, kind, items) => {
    setEmployees((current) => current.map((employee) => {
      if (employee.id !== employeeId) return employee;
      const existing = employee.payslipComponentsByPeriod?.[period] || employee.payslipComponents;
      const components = { earnings: existing?.earnings || earningsOf(employee, period), deductions: existing?.deductions || deductionsOf(employee, period), [kind]: items };
      return { ...employee, payslipComponentsByPeriod: { ...employee.payslipComponentsByPeriod, [period]: components } };
    }));
  };
  const updateEmployee = (employeeId, period, changes) => setEmployees((current) => current.map((employee) => employee.id === employeeId ? { ...employee, calculationInputsByPeriod: { ...employee.calculationInputsByPeriod, [period]: { ...employee.calculationInputsByPeriod?.[period], ...changes } } } : employee));
  const openEmail = (ids) => {
    const recipients = employees.filter((e) => ids.includes(e.id) && e.status === "Generated");
    if (!recipients.length) return updateNotice("Select generated payslips to start the email workflow.");
    setTemplate(Object.keys(TEMPLATES)[0]); setEmailPreviewId(recipients[0].id); setAttachPdf(true);
    setDialog({ type: "email", phase: "compose", ids: recipients.map((e) => e.id), period: month });
  };
  const fillTemplate = (text, employee) => text.replace(/\{\{(employee_name|employee_id|pay_period|net_pay|company_name)\}\}/g, (_, key) => ({ employee_name: employee.name, employee_id: employee.id, pay_period: monthOptions.find((m) => m.value === (dialog?.period || employee.payPeriod))?.label || dialog?.period || employee.payPeriod, net_pay: money(pay(employee, dialog?.period || employee.payPeriod).net), company_name: "Lernevo" })[key]);
  const sendEmails = (ids, retryOnly = false) => {
    const targets = employees.filter((e) => ids.includes(e.id) && e.status === "Generated" && (!retryOnly || e.emailStatus === "Failed"));
    if (!targets.length) return updateNotice("There are no failed emails to retry.");
    const period = dialog?.period || month;
    setEmployees((all) => all.map((e) => targets.some((t) => t.id === e.id) ? { ...e, emailStatus: "Sending" } : e)); setBusy(true);
    window.setTimeout(() => {
      const failed = targets.filter((e) => !retryOnly && e.id === "EMP012");
      setEmployees((all) => all.map((e) => targets.some((t) => t.id === e.id) ? { ...e, emailStatus: failed.some((f) => f.id === e.id) ? "Failed" : "Sent" } : e));
      setBusy(false); setDialog({ type: "email", phase: "result", ids: targets.map((e) => e.id), sent: targets.length - failed.length, failed: failed.length, period });
    }, 900);
  };
  const openExport = () => setDialog({ type: "export" });
  const exportData = (format) => {
    if (!rows.length) return updateNotice("There are no records to export for these filters.");
    const data = rows.map((e) => ({ ...(exportFields.details ? { Employee: e.name, "Employee ID": e.id, Email: e.email, Department: e.department } : {}), ...(exportFields.breakdown ? { "Basic Salary": e.basic, HRA: e.hra, "Other Allowances": e.special, PF: e.pf, "Professional Tax": e.tax, "Other Deductions": e.otherDeductions, "Gross Earnings": pay(e).earnings, "Total Deductions": pay(e).deductions } : {}), ...(exportFields.net ? { "Net Pay": pay(e).net } : {}) }));
    if (format === "Excel (.xlsx)") { const sheet = XLSX.utils.json_to_sheet(data); const book = XLSX.utils.book_new(); XLSX.utils.book_append_sheet(book, sheet, "Payslips"); XLSX.writeFile(book, `payslips-${month}.xlsx`); }
    else { const doc = new jsPDF(); doc.setFontSize(15); doc.text(`Lernevo Payslips — ${month}`, 15, 18); data.forEach((row, i) => { if (i && i % 25 === 0) doc.addPage(); doc.setFontSize(9); doc.text(Object.values(row).join(" · ").slice(0, 170), 15, 30 + (i % 25) * 9); }); doc.save(`payslips-${month}.pdf`); }
    setDialog(null); updateNotice(`${format} export downloaded successfully.`);
  };
  const modalTitle = dialog?.type === "teamForm" ? dialog.teamId ? "Edit Team" : "Add Team" : dialog?.type === "teamDelete" ? "Delete Team" : dialog?.type === "employeeForm" ? dialog.employeeId ? "Edit Employee Assignment" : "Add Employee to Team" : dialog?.type === "employeeRemove" ? "Remove Employee from Team" : dialog?.type === "generate" ? dialog.phase === "success" ? "Payslips Generated Successfully!" : "Preview Payslips" : dialog?.type === "email" ? dialog.phase === "confirm" ? "Confirm email delivery" : dialog.phase === "result" ? "Email delivery results" : "Send Payslips via Email" : dialog?.type === "how" ? "How It Works" : dialog?.type === "export" ? "Export payslips" : "Payslip preview";
  const allDepartments = [...new Set([...employees.map((employee) => employee.department), ...teams.flatMap((team) => team.departments || [])])].sort();

  return <div className="pay-admin-layout"><Sidebar/><main className="pay-admin-main">
    <header className="pay-admin-heading"><div><span className="pay-eyebrow">HR OPERATIONS</span><h1>Payslips</h1><p>Review, generate and send employee payslips.</p></div>{!showPayslipTypes && <div className="pay-header-actions"><button className="pay-btn pay-types-entry" onClick={() => setShowPayslipTypes(true)}><Layers size={16}/>Payslip Types</button><button className="pay-btn pay-btn-quiet" onClick={() => setDialog({ type: "how" })}><HelpCircle size={16}/>How It Works</button><button className="pay-btn pay-btn-quiet" onClick={openExport}><FileSpreadsheet size={16}/>Export</button></div>}</header>
    {showPayslipTypes ? <PayslipTypes onBack={() => setShowPayslipTypes(false)} onNotice={updateNotice}/> : <>
    <section className="pay-summary-grid"><Summary icon={<Users/>} label="Total employees" value={employees.length} note="Employee master records" tone="blue"/><Summary icon={<FileText/>} label="Generated payslips" value={employees.filter((e) => e.status === "Generated" && e.payPeriod === month).length} note="Ready to view and download" tone="green"/><Summary icon={<Clock3/>} label="Pending generation" value={employees.filter((e) => e.status === "Pending").length} note="Includes blocked records" tone="amber"/><Summary icon={<span className="pay-rupee">₹</span>} label="Net payroll" value={money(generated.reduce((sum, e) => sum + pay(e, month, effectiveType(e, teams.find((team) => team.employeeIds.includes(e.id))?.id).type).net, 0))} note="For selected pay period" tone="violet"/></section>
    <section className="pay-team-section"><div className="pay-team-heading"><div><h2>Teams</h2></div><div className="pay-team-heading-controls"><label><CalendarDays size={16}/><select aria-label="Team pay period" value={month} onChange={(event) => setMonth(event.target.value)}>{monthOptions.map((option) => <option key={option.value} value={option.value}>{option.label}</option>)}</select></label></div></div>
      <div className="pay-team-list">{teamGroups.map((team) => {
        const isOpen = expandedTeam === team.id;
        const teamEmployees = team.members.filter((employee) => (teamDepartmentFilter === "All departments" || employee.department === teamDepartmentFilter) && (teamEmployeeFilter === "All Employees" || employee.id === teamEmployeeFilter));
        return <article className={`pay-team-card${isOpen ? " is-open" : ""}`} key={team.id}>
          <div className="pay-team-row">
            <button className="pay-team-toggle" aria-label={`${isOpen ? "Collapse" : "Expand"} ${team.label}`} aria-expanded={isOpen} onClick={() => { setExpandedTeam(isOpen ? null : team.id); setTeamDepartmentFilter("All departments"); setTeamEmployeeFilter("All Employees"); }}><ChevronDown className="pay-team-chevron" size={17}/></button><span className="pay-team-icon"><Users size={19}/></span><span className="pay-team-title-actions"><strong className="pay-team-name">{team.label}</strong>{isAdmin && <><button className="pay-row-action" aria-label={`Edit ${team.label}`} title="Edit team" onClick={() => setDialog({ type: "teamForm", teamId: team.id })}><Pencil size={13}/></button><button className="pay-row-action danger" aria-label={`Delete ${team.label}`} title="Delete team" onClick={() => setDialog({ type: "teamDelete", teamId: team.id })}><Trash2 size={13}/></button></>}</span><span className="pay-team-count">{team.members.length} {team.members.length === 1 ? "employee" : "employees"}</span><span className="pay-team-type-badge">{teamPayslipTypes[team.id] || "Not Assigned"}</span><span className="pay-team-departments">{team.departmentCounts.map((department) => <i key={department.name}>{department.name} ({department.count})</i>)}</span><span className="pay-team-status generated"><FileText size={14}/><b>{team.generated}</b><small>Generated</small></span><span className="pay-team-status pending"><Clock3 size={14}/><b>{team.pending}</b><small>Pending</small></span><span className="pay-team-pay"><b>{money(team.net)}</b><small>Total net pay</small></span><ChevronDown className="pay-team-end-chevron" size={17}/>
          </div>
          {isOpen && <div className="pay-team-content"><div className="pay-team-filters"><label className="pay-team-filter">Department<select aria-label={`Filter ${team.label} employees by department`} value={teamDepartmentFilter} onChange={(event) => setTeamDepartmentFilter(event.target.value)}><option>All departments</option>{team.departmentCounts.map((department) => <option key={department.name}>{department.name}</option>)}</select></label><label className="pay-team-filter">Employee<select aria-label={`Filter ${team.label} employees`} value={teamEmployeeFilter} onChange={(event) => setTeamEmployeeFilter(event.target.value)}><option>All Employees</option>{team.members.map((employee) => <option key={employee.id} value={employee.id}>{employee.name}</option>)}</select></label><span className="pay-team-toolbar-actions"></span></div>
            <div className="pay-team-table-wrap"><table className="pay-team-table"><thead><tr><th>#</th><th>Employee</th><th>Payslip type</th><th>Department</th><th>Pay period</th><th>Net pay</th><th>Status</th>{isAdmin && <th>Actions</th>}</tr></thead><tbody>{teamEmployees.map((employee) => <tr key={employee.id}><td>{team.members.findIndex((member) => member.id === employee.id) + 1}</td><td><span className="pay-team-person"><strong>{employee.name}</strong><button aria-label={`Open ${employee.name} payslip details`} title="Payslip details" onClick={() => setDialog({ type: "employeeDetails", employeeId: employee.id, period: month })}><Plus size={14}/></button></span></td><td>{effectiveType(employee, team.id).type || "Not Assigned"}<small>{effectiveType(employee, team.id).source}</small></td><td>{employee.department}</td><td>{monthOptions.find((option) => option.value === employee.payPeriod)?.label || employee.payPeriod}</td><td><strong>{effectiveType(employee, team.id).type ? money(pay(employee, month, effectiveType(employee, team.id).type).net) : "—"}</strong></td><td><span className={`pay-status ${employee.status === "Generated" ? "is-generated" : "is-pending"}`}>{employee.status}</span></td>{isAdmin && <td><span className="pay-row-actions"><button className="pay-row-action" aria-label={`Edit ${employee.name} assignment`} title="Edit employee" onClick={() => setDialog({ type: "employeeForm", employeeId: employee.id, teamId: team.id })}><Pencil size={13}/></button><button className="pay-row-action danger" aria-label={`Remove ${employee.name} from ${team.label}`} title="Remove from team" onClick={() => setDialog({ type: "employeeRemove", employeeId: employee.id, teamId: team.id })}><Trash2 size={13}/></button></span></td>}</tr>)}{!teamEmployees.length && <tr><td colSpan={isAdmin ? "8" : "7"} className="pay-team-empty">No employees found for these filters.</td></tr>}</tbody></table></div>
          </div>}
        </article>;
      })}</div>
    </section>
    <p className="pay-demo-note">Illustrative team assignments are temporary; payroll amounts come from existing payslip records.</p>
    </>}
  </main>

  {dialog && <div className="pay-overlay" onMouseDown={closeDialog}><section key={dialog.type} className={`pay-modal ${["generate", "email", "view", "employeeDetails", "payslipPreview"].includes(dialog.type) ? "pay-workflow-modal" : ""} ${dialog.type === "employeeDetails" ? "pay-employee-modal" : ""} ${dialog.type === "payslipPreview" ? "pay-document-modal" : ""}`} role="dialog" aria-modal="true" aria-label={modalTitle} onMouseDown={(event) => event.stopPropagation()}><header className="pay-modal-header"><div><h2>{dialog.type === "employeeDetails" ? "Employee Payslip Details" : dialog.type === "payslipPreview" ? "Payslip Preview" : modalTitle}</h2>{dialog.type !== "how" && <p>{dialog.type === "employeeDetails" ? `${selectedPreview.name} · ${selectedPreview.id}` : dialog.type === "payslipPreview" ? "Review the employee payslip before downloading or printing." : dialog.type === "teamForm" ? "Edit the team name, departments, and description." : dialog.type === "teamDelete" ? "Confirm team removal after resolving all assignments." : dialog.type === "employeeForm" ? "Assign an existing employee and update their team details." : dialog.type === "employeeRemove" ? "Review the effect on the employee team assignment." : dialog.type === "generate" && dialog.phase === "success" ? `${dialog.ids.length} payslip${dialog.ids.length === 1 ? " has" : "s have"} been generated and ${dialog.ids.length === 1 ? "is" : "are"} ready to download or send via email.` : dialog.type === "email" && dialog.phase === "result" ? "Email status has been updated for each recipient." : dialog.type === "generate" ? "Review the payslip details before generating." : dialog.type === "email" ? "Review the email template and send payslips to the selected employees." : "A detailed view of the generated employee payslip."}</p>}</div><button className="pay-icon-button" onClick={closeDialog} aria-label="Close dialog"><X size={18}/></button></header>
    {dialog.type === "employeeDetails" && <EmployeePayslipDetails employee={selectedPreview} period={dialog.period || month} team={selectedTeamName} isAdmin={isAdmin} remarks={savedRemarks[`${selectedPreview.id}:${dialog.period || month}`] || []} onSaveRemarks={(remarks) => setSavedRemarks((current) => ({ ...current, [`${selectedPreview.id}:${dialog.period || month}`]: remarks }))} onUpdateEmployee={(changes) => updateEmployee(selectedPreview.id, dialog.period || month, changes)} onSaveComponents={(kind, items) => savePayrollComponents(selectedPreview.id, dialog.period || month, kind, items)} onCancel={closeDialog} onPreview={() => setDialog({ ...dialog, type: "payslipPreview" })} onGenerate={() => startEmployeeGeneration(selectedPreview)} onFeedback={updateNotice} />}
    {dialog.type === "payslipPreview" && <><PayslipPreview employee={selectedPreview} periodKey={dialog.period || month} period={monthOptions.find((option) => option.value === (dialog.period || month))?.label || dialog.period || month} team={selectedTeamName}/><div className="pay-modal-actions pay-preview-actions"><button className="pay-btn pay-btn-quiet" onClick={() => setDialog({ ...dialog, type: "employeeDetails" })}>Close Preview</button><button className="pay-btn pay-btn-quiet" onClick={() => downloadPdf(selectedPreview)}><Download size={15}/>Download PDF</button><button className="pay-btn pay-btn-primary" onClick={() => window.print()}>Print Payslip</button></div></>}
    {dialog.type === "teamForm" && <TeamForm key={`${dialog.teamId || "new"}`} team={teams.find((team) => team.id === dialog.teamId)} payslipType={teamPayslipTypes[dialog.teamId] || ""} departments={allDepartments} onSave={saveTeam} onCancel={closeDialog}/>}
    {dialog.type === "teamDelete" && (() => { const team = teams.find((item) => item.id === dialog.teamId); const count = team?.employeeIds.length || 0; return <div className="pay-management-dialog"><div className={`pay-management-warning${count ? " is-blocked" : ""}`}><AlertTriangle size={20}/><div><strong>{team?.label || "Team"}</strong><p>{count ? `This team contains ${count} assigned employee${count === 1 ? "" : "s"}. Reassign or remove each employee before deleting the team. No employee or payslip records will be deleted.` : "This empty team will be removed from the frontend demo."}</p></div></div><div className="pay-modal-actions"><button className="pay-btn pay-btn-quiet" onClick={closeDialog}>Cancel</button><button className="pay-btn pay-btn-danger" disabled={count > 0} onClick={() => removeTeam(team.id)}>Confirm Delete</button></div></div>; })()}
    {dialog.type === "employeeForm" && <TeamEmployeeForm key={`${dialog.employeeId || "new"}-${dialog.teamId}`} employee={employees.find((employee) => employee.id === dialog.employeeId)} teams={teams} teamId={dialog.teamId} payslipType={employeePayslipTypes[dialog.employeeId] || ""} teamPayslipTypes={teamPayslipTypes} departments={allDepartments} onSave={saveEmployeeAssignment} onCancel={closeDialog}/>}
    {dialog.type === "employeeRemove" && (() => { const employee = employees.find((item) => item.id === dialog.employeeId); const team = teams.find((item) => item.id === dialog.teamId); return <div className="pay-management-dialog"><div className="pay-management-warning"><AlertTriangle size={20}/><div><strong>{employee?.name || "Employee"} · {team?.label || "Team"}</strong><p>Remove this employee from the team assignment? Their employee master record, payslip status, and historical payroll data will remain available.</p></div></div><div className="pay-modal-actions"><button className="pay-btn pay-btn-quiet" onClick={closeDialog}>Cancel</button><button className="pay-btn pay-btn-danger" onClick={() => removeEmployeeAssignment(dialog)}>Confirm Remove</button></div></div>; })()}
    {dialog.type === "generate" && dialog.phase === "review" && <><div className="pay-review-layout"><aside className="pay-review-list"><strong>Selected employees ({dialog.ids.length})</strong>{dialog.ids.map((id) => { const e = employees.find((item) => item.id === id); return e && <button key={id} className={dialog.employeeId === id ? "active" : ""} onClick={() => setDialog({ ...dialog, employeeId: id })}><span><b>{e.name}</b><small>{e.id} · {e.department}</small></span><span>{money(pay(e, dialog.period, effectiveType(e, teams.find((team) => team.employeeIds.includes(e.id))?.id).type).net)}</span></button>; })}</aside><div className="pay-review-preview">{selectedPreview && <PayslipPreview employee={selectedPreview} periodKey={dialog.period} period={previewMonth} showSources onDownload={() => downloadPdf(selectedPreview)}/>}</div></div><div className="pay-modal-actions"><button className="pay-btn pay-btn-quiet" onClick={closeDialog}>Cancel</button><button className="pay-btn pay-btn-primary" disabled={busy} onClick={generate}>{busy ? "Generating payslips…" : `Confirm & Generate (${dialog.ids.length})`}</button></div></>}
    {dialog.type === "generate" && dialog.phase === "success" && <div className="pay-modal-body pay-success"><CheckCircle2 size={48}/><strong>{dialog.ids.length} payslip{dialog.ids.length === 1 ? " has" : "s have"} been generated successfully.</strong><span>Generation does not send email automatically.</span><div className="pay-modal-actions"><button className="pay-btn pay-btn-quiet" onClick={() => { setDialog(null); setMonth(dialog.period); }}>Return to Payslips</button><button className="pay-btn pay-btn-primary" onClick={() => openEmail(dialog.ids)}><Mail size={16}/>Send Email ({dialog.ids.length})</button></div></div>}
    {dialog.type === "view" && selectedPreview && <><PayslipPreview employee={selectedPreview} periodKey={dialog.period || month} period={previewMonth} onDownload={() => downloadPdf(selectedPreview)}/><div className="pay-modal-actions"><button className="pay-btn pay-btn-quiet" onClick={closeDialog}>Close</button><button className="pay-btn pay-btn-primary" onClick={() => downloadPdf(selectedPreview)}><Download size={16}/>Download Payslip</button></div></>}
    {dialog.type === "email" && dialog.phase === "compose" && <div className="pay-email-body"><div className="pay-recipient-card"><div><strong>Recipients · {dialog.ids.length}</strong><span>Each employee receives an individual email with only their own payslip.</span></div><div className="pay-recipient-chips">{dialog.ids.map((id) => { const e = employees.find((x) => x.id === id); return e && <button key={id} className={emailPreviewId === id ? "active" : ""} onClick={() => setEmailPreviewId(id)}>{e.name} · {e.email}</button>; })}</div></div><label className="pay-field">Email template<select value={template} onChange={(e) => setTemplate(e.target.value)}>{Object.keys(TEMPLATES).map((name) => <option key={name}>{name}</option>)}</select></label>{emailPreviewId && (() => { const e = employees.find((x) => x.id === emailPreviewId); if (!e) return null; const t = TEMPLATES[template]; const filename = `${e.name.replace(/\s+/g, "_")}_Payslip_${e.payPeriod.replace("-", "")}.pdf`; return <><label className="pay-field">Email subject<input className="pay-text-input" value={fillTemplate(t.subject, e)} readOnly/></label><label className="pay-field">Email message<textarea className="pay-message-input" value={fillTemplate(t.message, e)} readOnly rows="8"/></label><div className="pay-email-recipient"><Mail size={16}/><span><b>To: {e.name}</b><small>{e.email}</small></span></div><label className="pay-attachment"><input type="checkbox" checked={attachPdf} onChange={(event) => setAttachPdf(event.target.checked)}/><Paperclip size={17}/><span><b>Attach generated payslip PDF</b><small>{attachPdf ? filename : "No attachment"}</small></span></label></>; })()}<div className="pay-demo-callout">No real email is sent. Every recipient gets their own message and payslip attachment.</div><div className="pay-modal-actions"><button className="pay-btn pay-btn-quiet" onClick={closeDialog}>Cancel</button><button className="pay-btn pay-btn-quiet" onClick={() => setDialog({ ...dialog, phase: "preview" })}>Preview Email</button><button className="pay-btn pay-btn-primary" onClick={() => setDialog({ ...dialog, phase: "confirm" })}>Send Email ({dialog.ids.length})</button></div></div>}
    {dialog.type === "email" && dialog.phase === "preview" && <div className="pay-modal-body">{(() => { const e = employees.find((x) => x.id === emailPreviewId) || employees.find((x) => x.id === dialog.ids[0]); const t = TEMPLATES[template]; return e && <article className="pay-email-preview"><div><b>To</b><span>{e.name} &lt;{e.email}&gt;</span></div><div><b>Subject</b><span>{fillTemplate(t.subject, e)}</span></div><pre>{fillTemplate(t.message, e)}</pre>{attachPdf && <div className="pay-attachment-preview"><FileText size={18}/>{e.name.replace(/\s+/g, "_")}_Payslip_{e.payPeriod.replace("-", "")}.pdf</div>}</article>; })()}<p className="pay-demo-callout">Preview shows the employee-specific message and attachment. Bulk sends create separate emails per employee.</p><div className="pay-modal-actions"><button className="pay-btn pay-btn-quiet" onClick={() => setDialog({ ...dialog, phase: "compose" })}>Back to Email</button><button className="pay-btn pay-btn-primary" onClick={() => setDialog({ ...dialog, phase: "confirm" })}>Continue to Send Email ({dialog.ids.length})</button></div></div>}
    {dialog.type === "email" && dialog.phase === "confirm" && <div className="pay-modal-body pay-confirm"><Mail size={38}/><strong>{dialog.ids.some((id) => employees.find((e) => e.id === id)?.emailStatus === "Sent") ? "Resend" : "Send"} payslips to {dialog.ids.length} {dialog.ids.length === 1 ? "employee" : "employees"}?</strong><span>Each recipient will receive an individual email addressed to their registered email with only their own payslip attached.</span><div className="pay-confirm-recipients">{dialog.ids.map((id) => { const e = employees.find((x) => x.id === id); return e && <span key={id}>{e.name} · {e.email}</span>; })}</div><div className="pay-modal-actions"><button className="pay-btn pay-btn-quiet" disabled={busy} onClick={() => setDialog({ ...dialog, phase: "compose" })}>Cancel</button><button className="pay-btn pay-btn-primary" disabled={busy} onClick={() => sendEmails(dialog.ids)}>{busy ? "Sending…" : "Confirm & Send"}</button></div></div>}
    {dialog.type === "email" && dialog.phase === "result" && <div className="pay-modal-body pay-success"><CheckCircle2 size={44}/><strong>Payslip emails sent successfully.</strong><div className="pay-result-stats"><span>Total recipients <b>{dialog.ids.length}</b></span><span>Successfully sent <b>{dialog.sent}</b></span><span>Failed <b className={dialog.failed ? "failed-count" : ""}>{dialog.failed}</b></span></div>{dialog.failed > 0 && <p className="pay-failure-note">Failed emails remain available for retry from the Generated tab.</p>}<div className="pay-modal-actions"><button className="pay-btn pay-btn-quiet" onClick={closeDialog}>Close</button>{dialog.failed > 0 && <button className="pay-btn pay-btn-primary" onClick={() => sendEmails(dialog.ids, true)} disabled={busy}>{busy ? "Retrying…" : "Retry Failed"}</button>}</div></div>}
    {dialog.type === "how" && <div className="pay-modal-body"><ol className="pay-workflow">{["Select employees with approved timesheets and complete payroll data.", "Preview each employee’s earnings, deductions and net pay.", "Confirm to generate payslips. Generation never sends email.", "Choose an email template and preview the individual messages.", "Confirm simulated delivery and track each email status.", "View, download or retry failed emails from Generated."].map((step, i) => <li key={step}><span>{i + 1}</span>{step}</li>)}</ol><div className="pay-demo-callout">This module uses frontend demo data only. No backend service or email provider is called.</div></div>}
    {dialog.type === "export" && <div className="pay-modal-body"><label className="pay-field">Include in export</label><fieldset className="pay-export-fields">{[["details", "Employee details"], ["breakdown", "Earnings and deductions"], ["net", "Net pay"]].map(([key, label]) => <label key={key}><input type="checkbox" checked={exportFields[key]} onChange={() => setExportFields((fields) => ({ ...fields, [key]: !fields[key] }))}/>{label}</label>)}</fieldset><div className="pay-modal-actions"><button className="pay-btn pay-btn-quiet" onClick={() => exportData("PDF (.pdf)")}><FileText size={16}/>PDF</button><button className="pay-btn pay-btn-primary" onClick={() => exportData("Excel (.xlsx)")}><FileSpreadsheet size={16}/>Excel</button></div></div>}
  </section></div>}
  {notice && <div className="pay-toast" role="status">{notice}</div>}
  </div>;
}

function Summary({ icon, label, value, note, tone }) { return <article className={`pay-summary pay-${tone}`}><div className="pay-summary-top"><span>{label}</span><i>{icon}</i></div><strong>{value}</strong><small>{note}</small></article>; }
function EmployeePayslipDetails({ employee, period, team, isAdmin, remarks, onSaveRemarks, onUpdateEmployee, onSaveComponents, onCancel, onPreview, onGenerate, onFeedback }) {
  const [activeTab, setActiveTab] = useState("Earnings & Deductions");
  const [editingDays, setEditingDays] = useState(false);
  const [daysDraft, setDaysDraft] = useState(String(employee.days ?? ""));
  const [remarkDraft, setRemarkDraft] = useState("");
  const [isAddingRemark, setIsAddingRemark] = useState(false);
  const [editingRemarkId, setEditingRemarkId] = useState(null);
  const [deletingRemarkId, setDeletingRemarkId] = useState(null);
  const historyDate = (daysAgo) => new Date(Date.now() - daysAgo * 86400000).toLocaleString("en-IN", { day: "2-digit", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit" });
  const [history, setHistory] = useState(() => [
    { id: "reviewed", date: historyDate(2), action: "Payslip details reviewed", status: "Demo", comment: "Illustrative entry" },
    { id: "approval", date: historyDate(1), action: `Approval state: ${employee.approval}`, status: "Demo", comment: "Illustrative entry" },
    { id: "current", date: historyDate(0), action: `Current payslip status: ${employee.status}`, status: "Demo", comment: "Illustrative entry" },
  ]);
  const [editingHistoryId, setEditingHistoryId] = useState(null);
  const [historyDraft, setHistoryDraft] = useState({ action: "", comment: "" });
  const [deletingHistoryId, setDeletingHistoryId] = useState(null);
  const type = employee.payslipType;
  const totals = pay(employee, period, type);
  const earnings = earningsOf(employee, period);
  const deductions = deductionsOf(employee, period);
  const fixedSalary = earnings.filter((item) => ["basic", "hra", "special"].includes(item.id)).reduce((sum, item) => sum + Number(item.value || 0), 0);
  const recordedLeaveDays = Number.isFinite(employee.leaves) ? employee.leaves : null;
  const periodLabel = monthOptions.find((option) => option.value === period)?.label || period;
  const otherEarnings = earnings.filter((item) => !["basic", "hra", "special", "overtime"].includes(item.id)).reduce((sum, item) => sum + Number(item.value || 0), 0);
  const unpaidLeaveDeduction = deductions.filter((item) => item.id === "unpaid-leave").reduce((sum, item) => sum + Number(item.value || 0), 0);
  const otherDeductions = deductions.filter((item) => !["pf", "tax", "income-tax", "unpaid-leave", "other-deductions"].includes(item.id)).reduce((sum, item) => sum + Number(item.value || 0), 0);
  const calcInput = { monthlySalary: fixedSalary, hourlyRate: 250, regularHours: employee.hours || 160, overtimeHours: employee.overtimePay ? 4 : 0, overtimeRate: employee.overtimePay ? employee.overtimePay / 4 : 375, dailyRate: 1600, payableDays: employee.days || 20, weeklyRate: 12000, payableWeeks: 4, monthlyRate: fixedSalary, salesBase: 200000, commissionRate: 0.05, fixedComponent: 5000, eligibleUnits: 400, unitRate: 80, contractAmount: 60000, contractPayable: 30000, ...(employee.calculationInputsByPeriod?.[period] || {}) };
  const calculationRows = (() => {
    let rows;
    if (type === "Hourly Pay") rows = [["Salary Type", "Hourly Pay - demonstration defaults", "-", "Demo"], ["Hourly Rate", "Rate per regular hour", money(calcInput.hourlyRate), "Input", "hourlyRate"], ["Regular Hours", "Regular payable hours; overtime excluded", money(calcInput.regularHours * calcInput.hourlyRate), "Input", "regularHours"], ["Overtime Hours", "Approved hours", String(calcInput.overtimeHours), "Input", "overtimeHours"], ["Overtime Rate", "Applicable rate", money(calcInput.overtimeRate), "Input", "overtimeRate"]];
    else if (type === "Daily Wage") rows = [["Salary Type", "Daily Wage - demonstration defaults", "-", "Demo"], ["Daily Wage Rate", "Rate per payable day", money(calcInput.dailyRate), "Input", "dailyRate"], ["Payable Days", "Eligible days in this period", String(calcInput.payableDays), "Input", "payableDays"], ["Base Pay", "Payable days x daily wage rate", money(calcInput.payableDays * calcInput.dailyRate), "Calculated"]];
    else if (type === "Weekly Pay") rows = [["Salary Type", "Weekly Pay - complete weeks policy", "-", "Demo"], ["Weekly Rate", "Agreed weekly rate", money(calcInput.weeklyRate), "Input", "weeklyRate"], ["Payable Weeks", "Complete payable weeks", String(calcInput.payableWeeks), "Input", "payableWeeks"], ["Payable Amount", "Payable weeks x weekly rate", money(calcInput.payableWeeks * calcInput.weeklyRate), "Calculated"]];
    else if (type === "Monthly Pay") rows = [["Salary Type", "Monthly Pay - full period amount", "-", "Demo"], ["Agreed Monthly Salary", "No proration configured for this demo", money(calcInput.monthlyRate), "Input", "monthlyRate"]];
    else if (type === "Commission-Based Pay") rows = [["Salary Type", "Commission-Based Pay - demonstration defaults", "-", "Demo"], ["Commission Base", "Eligible sales or transactions", money(calcInput.salesBase), "Input", "salesBase"], ["Commission Rate", "Rate applied to eligible base", String(calcInput.commissionRate * 100) + "%", "Input", "commissionRate"], ["Fixed Component", "Applicable fixed component", money(calcInput.fixedComponent), "Input", "fixedComponent"]];
    else if (type === "Piece-Rate Pay") rows = [["Salary Type", "Piece-Rate Pay - demonstration defaults", "-", "Demo"], ["Eligible Units", "Approved completed units", String(calcInput.eligibleUnits), "Input", "eligibleUnits"], ["Rate Per Unit", "Amount per eligible unit", money(calcInput.unitRate), "Input", "unitRate"]];
    else if (type === "Contract-Based Pay") rows = [["Salary Type", "Contract-Based Pay - approved milestone", "-", "Demo"], ["Agreed Contract Amount", "Not divided by calendar days", money(calcInput.contractAmount), "Input", "contractAmount"], ["Approved Payable Amount", "Approved milestone amount", money(calcInput.contractPayable), "Input", "contractPayable"]];
    else rows = [["Salary Type", type || "Not Assigned", "-", "Demo"], ["Monthly Fixed Salary", "Basic + HRA + Special Allowance", money(calcInput.monthlySalary), "Edit components"], ["Monthly Working Days", "22 working days (demo assumption)", "22 days", "Demo"], ["Payable Working Days", "Demo days used in proration", String(calcInput.payableDays) + " days", "Input", "payableDays"], ["Per-Day Rate", money(calcInput.monthlySalary) + " / 22", money(calcInput.monthlySalary / 22), "Demo"], ["Prorated Salary", money(calcInput.monthlySalary / 22) + " x " + calcInput.payableDays, money(calcInput.monthlySalary / 22 * calcInput.payableDays), "Demo"], ["Overtime", String(calcInput.overtimeHours) + " hours x " + money(calcInput.overtimeRate), money(calcInput.overtimeHours * calcInput.overtimeRate), "Demo"]];
    return rows.concat([["Allowances / Other Earnings", "Applicable earning components", money(earnings.filter((item) => !["basic", "overtime"].includes(item.id)).reduce((sum, item) => sum + Number(item.value || 0), 0)), "Edit components"], ["Total Earnings", "Type formula + applicable earnings", money(totals.earnings), "Calculated"], ["Total Deductions", "Sum of editable deduction components", money(totals.deductions), "Calculated"], ["Final Net Pay", "Total earnings less total deductions", money(totals.net), "Calculated"]]);
  })();
  const saveDays = () => { const value = Number(daysDraft); if (!Number.isFinite(value) || value < 0) return onFeedback("Actual days worked must be a non-negative number."); onUpdateEmployee({ days: value }); setEditingDays(false); };
  const saveRemark = () => {
    const text = remarkDraft.trim();
    if (!text) return onFeedback("Enter a remark before saving.");
    if (editingRemarkId) onSaveRemarks(remarks.map((item) => item.id === editingRemarkId ? { ...item, comment: text, updatedAt: new Date().toLocaleString("en-IN") } : item));
    else onSaveRemarks([...remarks, { id: `remark-${Date.now()}`, comment: text, author: "Super Admin (demo)", date: new Date().toLocaleString("en-IN") }]);
    setRemarkDraft(""); setEditingRemarkId(null); setIsAddingRemark(false); onFeedback("Remark saved in frontend demo state.");
  };
  const startRemarkEdit = (remark) => { setRemarkDraft(remark.comment); setEditingRemarkId(remark.id); setIsAddingRemark(true); setDeletingRemarkId(null); };
  const deleteRemark = (id) => { onSaveRemarks(remarks.filter((item) => item.id !== id)); setDeletingRemarkId(null); if (editingRemarkId === id) { setEditingRemarkId(null); setRemarkDraft(""); setIsAddingRemark(false); } onFeedback("Remark deleted from frontend demo state."); };
  const startHistoryEdit = (event) => { setEditingHistoryId(event.id); setHistoryDraft({ action: event.action, comment: event.comment || "" }); setDeletingHistoryId(null); };
  const saveHistoryEdit = () => { if (!historyDraft.action.trim()) return onFeedback("Enter a history description before saving."); setHistory((current) => current.map((event) => event.id === editingHistoryId ? { ...event, action: historyDraft.action.trim(), comment: historyDraft.comment.trim() } : event)); setEditingHistoryId(null); onFeedback("Illustrative history entry updated in this demo."); };
  const deleteHistory = (id) => { setHistory((current) => current.filter((event) => event.id !== id)); setDeletingHistoryId(null); onFeedback("Illustrative history entry deleted from this demo."); };
  return <div className="pay-employee-details-body">
    <section className="pay-employee-identity"><span className="pay-employee-avatar">{employee.name.split(" ").map((part) => part[0]).join("")}</span><div className="pay-employee-main"><strong>{employee.name}</strong><span>{employee.email}</span></div><div className="pay-employee-meta"><span><small>Employee ID</small><b>{employee.id}</b></span><span><small>Department</small><b>{employee.department}</b></span><span><small>Team</small><b>{team}</b></span><span><small>Payslip type</small><b>{employee.payslipType || "Not Assigned"} · {employee.payslipTypeSource || ""}</b></span><span><small>Employment type</small><b>Not specified</b></span><span><small>Pay period</small><b>{periodLabel}</b></span><span><small>Payslip status</small><b className={employee.status === "Generated" ? "pay-meta-generated" : "pay-meta-pending"}>{employee.status}</b></span></div></section>
    <div className="pay-employee-tabs" role="tablist" aria-label="Employee payslip details">{["Earnings & Deductions", "Pay Calculation", "Remarks & History"].map((tab) => <button key={tab} role="tab" aria-selected={activeTab === tab} className={activeTab === tab ? "active" : ""} onClick={() => setActiveTab(tab)}>{tab}</button>)}</div>
    <div className={`pay-earnings-content${activeTab === "Earnings & Deductions" ? "" : " pay-tab-hidden"}`}><div className="pay-detail-columns"><PayrollComponentList title="Earnings" kind="earnings" items={earnings} total={totals.earnings} editable={isAdmin} onSave={(items) => onSaveComponents("earnings", items)}/><PayrollComponentList title="Deductions" kind="deductions" items={deductions} editable={isAdmin} onSave={(items) => onSaveComponents("deductions", items)}/></div><div className="pay-detail-net"><span>Net Pay<small>Automatically recalculated from the listed components</small></span><strong>{money(totals.net)}</strong></div><p className="pay-detail-note">Frontend demo edits update this employee and pay period in page state only. No payroll policy or missing component is inferred.</p></div>
    <div className={`pay-calculation-content${activeTab === "Pay Calculation" ? "" : " pay-tab-hidden"}`}><div className="pay-calculation-table-wrap"><table className="pay-calculation-table"><thead><tr><th>Description</th><th>Calculation / Details</th><th>Amount (₹)</th><th>Actions</th></tr></thead><tbody>{calculationRows.map(([description, detail, amount, action, field]) => <tr className={["Total Earnings", "Total Deductions", "Final Net Pay"].includes(description) ? "pay-calculation-total" : ""} key={description}><td>{description}</td><td>{description === "Actual Days Worked" && editingDays ? <input className="pay-inline-number" type="number" min="0" step="1" value={daysDraft} onChange={(event) => setDaysDraft(event.target.value)} aria-label="Actual days worked"/> : detail}</td><td>{action === "Input" ? <input className="pay-inline-number" aria-label={description} type="number" min="0" step="0.01" value={calcInput[field]} onChange={(event) => { const value = Number(event.target.value); if (event.target.value !== "" && Number.isFinite(value) && value >= 0) onUpdateEmployee({ [field]: value }); }}/>: description === "Actual Days Worked" && editingDays ? `${daysDraft || 0} days` : amount}</td><td>{action === "Edit" && isAdmin ? editingDays ? <span className="pay-inline-actions"><button className="pay-icon-button" aria-label="Save actual days" onClick={saveDays}><Save size={13}/></button><button className="pay-icon-button" aria-label="Cancel actual days edit" onClick={() => { setEditingDays(false); setDaysDraft(String(employee.days ?? "")); }}><X size={13}/></button></span> : <button className="pay-calc-edit" onClick={() => { setDaysDraft(String(employee.days ?? "")); setEditingDays(true); }}>Edit</button> : action === "Edit components" && isAdmin ? <button className="pay-calc-edit" onClick={() => setActiveTab("Earnings & Deductions")}>Edit components</button> : <small className="pay-calc-readonly">{action}</small>}</td></tr>)}</tbody></table></div><p className="pay-detail-note">All figures use labeled frontend demonstration defaults. Editing here updates only this page state; no payroll record is persisted.</p></div>
    <div className={`pay-remarks-history${activeTab === "Remarks & History" ? "" : " pay-tab-hidden"}`}><section className="pay-remarks-panel"><div className="pay-remarks-heading"><div><h3>Remarks for This Pay Period</h3><p>For {employee.name} · {periodLabel}</p></div><span>Frontend demo · not permanently saved</span></div>{isAdmin && <><button className="pay-btn pay-btn-quiet pay-small-add" onClick={() => { setIsAddingRemark(true); setDeletingRemarkId(null); }}><Plus size={13}/>Add Remark</button>{isAddingRemark && <><textarea maxLength={1000} value={remarkDraft} onChange={(event) => setRemarkDraft(event.target.value)} placeholder={editingRemarkId ? "Edit this remark…" : "Write a new remark…"} aria-label="Remark for this pay period"/><div className="pay-remark-actions"><small>{remarkDraft.length}/1000 characters</small><span><button className="pay-btn pay-btn-quiet" onClick={() => { setEditingRemarkId(null); setRemarkDraft(""); setIsAddingRemark(false); }}>Cancel</button><button className="pay-btn pay-btn-primary" onClick={saveRemark}><Save size={13}/>{editingRemarkId ? "Save Changes" : "Save Remark"}</button></span></div></>}</>}{!remarks.length && <p className="pay-detail-note">No remarks saved for this employee and pay period.</p>}<div className="pay-remarks-list">{remarks.map((remark) => <article key={remark.id} className="pay-remark-item"><div><strong>{remark.comment}</strong><small>{remark.author || "Author not recorded"} · {remark.date || remark.updatedAt}</small></div>{isAdmin && <span className="pay-row-actions"><button className="pay-row-action" aria-label="Edit remark" onClick={() => startRemarkEdit(remark)}><Pencil size={13}/></button><button className="pay-row-action danger" aria-label="Delete remark" onClick={() => setDeletingRemarkId(remark.id)}><Trash2 size={13}/></button></span>}{deletingRemarkId === remark.id && <div className="pay-inline-confirm">Delete this demo remark? <button onClick={() => deleteRemark(remark.id)}>Confirm Delete</button><button onClick={() => setDeletingRemarkId(null)}>Cancel</button></div>}</article>)}</div></section><section className="pay-history-panel"><div className="pay-history-heading"><h3>Payslip History</h3><span>Illustrative demo history · not an audit log</span></div><ol className="pay-history-list">{history.map((event) => <li key={event.id}><i/><div>{editingHistoryId === event.id ? <div className="pay-history-edit"><input value={historyDraft.action} onChange={(inputEvent) => setHistoryDraft((current) => ({ ...current, action: inputEvent.target.value }))} aria-label="History action"/><textarea value={historyDraft.comment} onChange={(inputEvent) => setHistoryDraft((current) => ({ ...current, comment: inputEvent.target.value }))} aria-label="History comment"/><span><button onClick={saveHistoryEdit}>Save</button><button onClick={() => setEditingHistoryId(null)}>Cancel</button></span></div> : <><span>{event.date}</span><strong>{event.action}</strong><small>Responsible person: Not recorded · {event.comment}</small></>}{deletingHistoryId === event.id && <div className="pay-inline-confirm">Delete this illustrative event? <button onClick={() => deleteHistory(event.id)}>Confirm Delete</button><button onClick={() => setDeletingHistoryId(null)}>Cancel</button></div>}</div><b>{event.status}</b>{isAdmin && editingHistoryId !== event.id && deletingHistoryId !== event.id && <span className="pay-row-actions"><button className="pay-row-action" aria-label="Edit illustrative history entry" onClick={() => startHistoryEdit(event)}><Pencil size={12}/></button><button className="pay-row-action danger" aria-label="Delete illustrative history entry" onClick={() => setDeletingHistoryId(event.id)}><Trash2 size={12}/></button></span>}</li>)}</ol></section></div>
    <footer className="pay-employee-modal-footer"><button className="pay-btn pay-btn-quiet" onClick={onCancel}>Cancel</button><div><button className="pay-btn pay-btn-quiet" onClick={onPreview}>Preview Payslip</button><button className="pay-btn pay-btn-primary" onClick={onGenerate} disabled={!employee.payslipType} title={!employee.payslipType ? "Assign a payslip type before generation" : "Generate payslip"}>Generate Payslip</button></div></footer>
  </div>;
}

function PayrollComponentList({ title, kind, items, total, editable, onSave }) {
  const [editingId, setEditingId] = useState(null);
  const [draft, setDraft] = useState({ label: "", value: "" });
  const [isAdding, setIsAdding] = useState(false);
  const [deletingId, setDeletingId] = useState(null);
  const [error, setError] = useState("");
  const startEdit = (item) => { setDraft({ label: item.label, value: String(item.value) }); setEditingId(item.id); setIsAdding(false); setError(""); };
  const startAdd = () => { setDraft({ label: "", value: "" }); setEditingId(null); setIsAdding(true); setError(""); };
  const save = () => {
    const label = draft.label.trim(); const value = Number(draft.value);
    if (!label || draft.value.trim() === "" || !Number.isFinite(value) || value < 0) return setError("Enter a name and a valid non-negative amount.");
    const updated = isAdding ? [...items, { id: `${kind}-${Date.now()}`, label, value }] : items.map((item) => item.id === editingId ? { ...item, label, value } : item);
    onSave(updated); setEditingId(null); setIsAdding(false); setDraft({ label: "", value: "" }); setError("");
  };
  const cancel = () => { setEditingId(null); setIsAdding(false); setDraft({ label: "", value: "" }); setError(""); };
  const remove = (id) => { onSave(items.filter((item) => item.id !== id)); setDeletingId(null); };
  const rows = isAdding ? [...items, { id: "__new__", label: "", value: 0 }] : items;
  return <section className="pay-detail-panel"><h3>{title}</h3>{rows.map((item) => <div className={`pay-detail-amount-row${item.id === "__new__" || editingId === item.id ? " is-editing" : ""}`} key={item.id}>{editingId === item.id || item.id === "__new__" ? <><label><span>Component name</span><input value={draft.label} onChange={(event) => setDraft((current) => ({ ...current, label: event.target.value }))}/></label><label><span>Amount (₹)</span><input type="number" min="0" step="0.01" value={draft.value} onChange={(event) => setDraft((current) => ({ ...current, value: event.target.value }))}/></label><span className="pay-inline-actions"><button className="pay-icon-button" aria-label="Save component" onClick={save}><Save size={13}/></button><button className="pay-icon-button" aria-label="Cancel component edit" onClick={cancel}><X size={13}/></button></span>{error && <small className="pay-inline-error">{error}</small>}</> : <><span>{item.label}</span><strong>{money(item.value)}</strong>{editable && <span className="pay-row-actions"><button className="pay-row-action" aria-label={`Edit ${item.label}`} title="Edit component" disabled={Boolean(editingId || isAdding)} onClick={() => startEdit(item)}><Pencil size={12}/></button><button className="pay-row-action danger" aria-label={`Delete ${item.label}`} title="Delete component" disabled={Boolean(editingId || isAdding)} onClick={() => setDeletingId(item.id)}><Trash2 size={12}/></button></span>}{deletingId === item.id && <span className="pay-inline-confirm">Delete {item.label}? <button onClick={() => remove(item.id)}>Confirm Delete</button><button onClick={() => setDeletingId(null)}>Cancel</button></span>}</>}</div>)}{!rows.length && !isAdding && <p className="pay-detail-note">No components.</p>}{editable && <button className="pay-btn pay-btn-quiet pay-small-add" disabled={Boolean(editingId || isAdding)} onClick={startAdd}><Plus size={13}/>Add {title === "Earnings" ? "Earning" : "Deduction"}</button>}<div className="pay-detail-total"><strong>Total {title}</strong><b>{money(total ?? items.reduce((sum, item) => sum + Number(item.value || 0), 0))}</b></div></section>;
}

function TeamForm({ team, departments, payslipType: initialPayslipType, onSave, onCancel }) {
  const [label, setLabel] = useState(team?.label || "");
  const [selectedDepartments, setSelectedDepartments] = useState(team?.departments || []);
  const [description, setDescription] = useState(team?.description || "");
  const [payslipType, setPayslipType] = useState(initialPayslipType);
  const toggleDepartment = (department) => setSelectedDepartments((current) => current.includes(department) ? current.filter((item) => item !== department) : [...current, department]);
  return <form className="pay-management-dialog" onSubmit={(event) => { event.preventDefault(); onSave({ id: team?.id, label, departments: selectedDepartments, description, payslipType }); }}><label className="pay-field">Team Name<input className="pay-text-input" required value={label} onChange={(event) => setLabel(event.target.value)} placeholder="e.g. Team F"/></label><fieldset className="pay-management-departments"><legend>Departments</legend>{departments.map((department) => <label key={department}><input type="checkbox" checked={selectedDepartments.includes(department)} onChange={() => toggleDepartment(department)}/>{department}</label>)}{!departments.length && <small>No department values available yet.</small>}</fieldset>{team && <label className="pay-field">Payslip Type<select value={payslipType} onChange={(event) => setPayslipType(event.target.value)}><option value="">Select payslip type</option>{PAYSLIP_TYPES.map((type) => <option key={type} value={type}>{type}</option>)}</select></label>}<label className="pay-field">Description (Optional)<textarea className="pay-message-input" rows="3" value={description} onChange={(event) => setDescription(event.target.value)} placeholder="Add a short team description"/></label><div className="pay-modal-actions"><button type="button" className="pay-btn pay-btn-quiet" onClick={onCancel}>Cancel</button><button className="pay-btn pay-btn-primary"><Save size={14}/>{team ? "Save Changes" : "Save Team"}</button></div><small className="pay-demo-callout">Team changes are held in frontend demo state only.</small></form>;
}

function TeamEmployeeForm({ employee, teams, teamId, departments, payslipType: initialPayslipType, teamPayslipTypes, onSave, onCancel }) {
  const [employeeId, setEmployeeId] = useState(employee?.id || "");
  const [assignedTeamId, setAssignedTeamId] = useState(teamId || "");
  const [department, setDepartment] = useState(employee?.department || departments[0] || "");
  const [payPeriod, setPayPeriod] = useState(employee?.payPeriod || currentMonth);
  const [payslipType, setPayslipType] = useState(initialPayslipType);
  const assignedTeamType = teamPayslipTypes[assignedTeamId] || "";
  const selectedEmployee = INITIAL_EMPLOYEES.find((item) => item.id === employeeId);
  const currentTeam = teams.find((team) => team.employeeIds.includes(employeeId));
  const chooseEmployee = (id) => { setEmployeeId(id); const master = INITIAL_EMPLOYEES.find((item) => item.id === id); if (master) setDepartment(master.department); };
  return <form className="pay-management-dialog" onSubmit={(event) => { event.preventDefault(); onSave({ employeeId, teamId: assignedTeamId, department, payPeriod, payslipType: employee ? payslipType : undefined }); }}><label className="pay-field">Employee<select value={employeeId} onChange={(event) => chooseEmployee(event.target.value)} required disabled={Boolean(employee)}><option value="">Select an existing employee</option>{INITIAL_EMPLOYEES.map((item) => <option key={item.id} value={item.id}>{item.name} · {item.id}</option>)}</select></label>{selectedEmployee && currentTeam && currentTeam.id !== assignedTeamId && <p className="pay-demo-callout">{selectedEmployee.name} is currently assigned to {currentTeam.label}. Saving will move that assignment; the employee record and payslips stay intact.</p>}<label className="pay-field">Team<select value={assignedTeamId} onChange={(event) => setAssignedTeamId(event.target.value)} required>{teams.map((team) => <option key={team.id} value={team.id}>{team.label}</option>)}</select></label><label className="pay-field">Department<select value={department} onChange={(event) => setDepartment(event.target.value)} required>{departments.map((item) => <option key={item} value={item}>{item}</option>)}</select></label><label className="pay-field">Pay period<select value={payPeriod} onChange={(event) => setPayPeriod(event.target.value)} required>{monthOptions.map((option) => <option key={option.value} value={option.value}>{option.label}</option>)}</select></label>{employee && <label className="pay-field">Payslip Type<select value={payslipType} onChange={(event) => setPayslipType(event.target.value)}><option value="">Use team default{assignedTeamType ? ` (${assignedTeamType})` : " (Not Assigned)"}</option>{PAYSLIP_TYPES.map((type) => <option key={type} value={type}>{type}</option>)}</select></label>}<div className="pay-modal-actions"><button type="button" className="pay-btn pay-btn-quiet" onClick={onCancel}>Cancel</button><button className="pay-btn pay-btn-primary"><Save size={14}/>{employee ? "Save Changes" : "Assign Employee"}</button></div><small className="pay-demo-callout">Assignments are frontend demo state only. Existing employee master records and payslip data are preserved.</small></form>;
}
function PayslipPreview({ employee, period, periodKey = employee.payPeriod, team = "Not assigned", showSources = false, onDownload }) {
  const p = pay(employee, periodKey, employee.payslipType);
  return <div className="pay-slip"><div className="pay-slip-brand"><div className="pay-logo">L</div><span><strong>Lernevo</strong><small>People &amp; Culture</small></span><b>EMPLOYEE PAYSLIP</b></div><div className="pay-slip-period"><strong>{period}</strong><span>{employee.payslipNumber ? `Payslip No. · ${employee.payslipNumber}` : "Preview · not generated"}</span></div><div className="pay-slip-details"><Info label="Employee" value={employee.name}/><Info label="Employee ID" value={employee.id}/><Info label="Department" value={employee.department}/><Info label="Team" value={team}/><Info label="Payslip Type" value={employee.payslipType || "Not Assigned"}/><Info label="Employment Type" value="Not specified"/><Info label="Pay Period" value={period}/><Info label="Joining Date" value={employee.joining || "Not available"}/><Info label="Payment Date" value="Not recorded"/></div><div className="pay-slip-columns"><PayLines title="Earnings" rows={earningsOf(employee, periodKey).map(({ label, value }) => [label, value])} total={p.earnings} totalLabel="Total earnings"/><PayLines title="Deductions" rows={deductionsOf(employee, periodKey).map(({ label, value }) => [label, value])} total={p.deductions} totalLabel="Total deductions"/></div><div className="pay-net"><span>Net pay</span><strong>{money(p.net)}</strong></div>{showSources && <div className="pay-data-sources"><b>Data Sources</b><span>Existing employee salary fields and payslip deduction fields</span></div>}<small className="pay-slip-footnote">{employee.payslipNumber ? "Generated demo payslip · INR" : "Preview only · no payslip has been generated"}</small>{onDownload && <div className="pay-inline-download"><button className="pay-btn pay-btn-quiet" onClick={onDownload}><Download size={15}/>Download PDF</button></div>}</div>;
}
function Info({ label, value }) { return <div className="pay-info"><span>{label}</span><strong>{value}</strong></div>; }
function PayLines({ title, rows, total, totalLabel }) { return <div className="pay-lines"><h3>{title}</h3>{rows.map(([label, value]) => <div key={label}><span>{label}</span><span>{money(value)}</span></div>)}<div className="pay-lines-total"><strong>{totalLabel}</strong><strong>{money(total)}</strong></div></div>; }
